import SwiftUI

enum DeepSeekIconKind {
    case fish, think, search, read, terminal, edit, code, sparkle, inspect, checklist, question, skill, stop, trash, cordis, close, closeFill
    case goal, pause, play
    case chevronDown, chevronLeft, chevronRight, copy, check, branch, like, dislike, plus, send
    case newChat, personalization, projectAdd, refresh, ellipsis, settings, panelLeft, download
    case folderOpen, folderClosed, triangleRight
}

struct DeepSeekIcon: View {
    let kind: DeepSeekIconKind
    var size: CGFloat = 14

    var body: some View {
        Canvas { context, canvasSize in
            let source = sourceSize
            let scale = min(canvasSize.width / source.width, canvasSize.height / source.height)
            var transform = CGAffineTransform(scaleX: scale, y: scale)
            transform = transform.translatedBy(x: (canvasSize.width / scale - source.width) / 2,
                                               y: (canvasSize.height / scale - source.height) / 2)
            for (index, path) in paths.enumerated() {
                let transformed = path.applying(transform)
                if kind == .goal, index > 0 {
                    context.stroke(transformed, with: .foreground, lineWidth: 1.3 * scale)
                } else {
                    context.fill(transformed, with: .foreground,
                                 style: FillStyle(eoFill: kind == .branch, antialiased: true))
                }
            }
        }
        .frame(width: size, height: kind == .fish ? size * 17.04 / 23.16 : size)
        .accessibilityHidden(true)
    }

    private var sourceSize: CGSize {
        if kind == .fish { return CGSize(width: 23.16, height: 17.04) }
        if kind == .think || kind == .terminal || kind == .checklist || kind == .question || kind == .cordis || kind == .closeFill || kind == .chevronDown || kind == .chevronLeft || kind == .chevronRight { return CGSize(width: 14, height: 14) }
        return CGSize(width: 16, height: 16)
    }

    private var paths: [Path] {
        switch kind {
        case .fish:
            return [Self.svgPath(Self.fish)]
        case .think:
            return [Self.svgPath(Self.thinkDot), Self.svgPath(Self.thinkOrbit)]
        case .search:
            return [Self.svgPath(Self.searchLens), Self.svgPath(Self.searchHandle)]
        case .read:
            return [Self.svgPath(Self.readLine1), Self.svgPath(Self.readLine2), Self.svgPath(Self.readPage)]
        case .terminal:
            return [Self.svgPath(Self.terminalBox), Self.svgPath(Self.terminalArrow), Self.svgPath(Self.terminalLine)]
        case .edit:
            return [Self.svgPath(Self.edit)]
        case .code:
            return [Self.svgPath(Self.code)]
        case .sparkle:
            return [Self.svgPath(Self.sparkle1), Self.svgPath(Self.sparkle2), Self.svgPath(Self.sparkle3)]
        case .inspect:
            return [Self.svgPath(Self.inspect)]
        case .checklist:
            return Self.checklist.map(Self.svgPath)
        case .question:
            return Self.question.map(Self.svgPath)
        case .skill:
            return Self.skill.map(Self.svgPath)
        case .stop:
            return [Self.svgPath(Self.stop)]
        case .trash:
            return [Self.svgPath(Self.trash)]
        case .cordis:
            return [Self.svgPath(Self.cordisFrame), Self.svgPath(Self.cordisCenter)]
        case .close:
            return [Self.svgPath(Self.closeA), Self.svgPath(Self.closeB)]
        case .closeFill:
            return [Self.svgPath(Self.closeFill)]
        case .goal:
            return [Self.svgPath(Self.goalBody), Self.svgPath(Self.goalLine), Self.svgPath(Self.goalArrow)]
        case .pause:
            return [Self.svgPath(Self.pauseRing), Self.svgPath(Self.pauseLeft), Self.svgPath(Self.pauseRight)]
        case .play:
            return [Self.svgPath(Self.playRing), Self.svgPath(Self.playTriangle)]
        case .chevronDown:
            return [Self.svgPath(Self.chevronDown)]
        case .chevronLeft:
            return [Self.svgPath(Self.chevronLeft)]
        case .chevronRight:
            return [Self.svgPath(Self.chevronRight)]
        case .copy:
            return [Self.svgPath(Self.copy)]
        case .check:
            return [Self.svgPath(Self.check)]
        case .branch:
            return [Self.svgPath(Self.branch)]
        case .like:
            return [Self.svgPath(Self.like)]
        case .dislike:
            return [Self.svgPath(Self.dislike)]
        case .plus:
            return [Self.svgPath(Self.plus)]
        case .send:
            return [Self.svgPath(Self.send)]
        case .newChat:
            return [Self.svgPath(Self.newChat)]
        case .personalization:
            return [Self.svgPath(Self.personalization).applying(CGAffineTransform(translationX: 1.292, y: 1.3))]
        case .projectAdd:
            return [
                Self.svgPath(Self.projectAddPlus).applying(CGAffineTransform(translationX: 9.52, y: 2.52)),
                Self.svgPath(Self.projectAddFolder).applying(CGAffineTransform(translationX: 0.3496, y: 2.35)),
            ]
        case .refresh:
            return [Self.svgPath(Self.refresh)]
        case .ellipsis:
            return Self.ellipsis.map(Self.svgPath)
        case .settings:
            return [Self.svgPath(Self.settings)]
        case .panelLeft:
            return [Self.svgPath(Self.panelLeft)]
        case .download:
            return [Self.svgPath(Self.download)]
        case .folderOpen:
            return [Self.svgPath(Self.folderOpen)]
        case .folderClosed:
            return [Self.svgPath(Self.folderClosed).applying(CGAffineTransform(translationX: 1.5, y: 2.429))]
        case .triangleRight:
            return [Self.svgPath(Self.triangleRight)]
        }
    }

    /// Tiny SVG path reader for the exact repository glyph geometry. The
    /// product assets use only M/L/H/V/C/Q/Z, so no rasterization is involved.
    /// Shared by the other repository-derived glyphs in the native client.
    /// Keep this reader code-native: no WebKit or rasterized SVG bridge.
    static func svgPath(_ source: String) -> Path {
        let pattern = #"[MLHVQCZmlhvqcz]|[-+]?(?:\d*\.\d+|\d+\.?)(?:[eE][-+]?\d+)?"#
        let expression = try! NSRegularExpression(pattern: pattern)
        let range = NSRange(source.startIndex..., in: source)
        let tokens = expression.matches(in: source, range: range).compactMap { match -> String? in
            guard let value = Range(match.range, in: source) else { return nil }
            return String(source[value])
        }
        var result = Path()
        var index = 0
        var command = ""
        var current = CGPoint.zero
        var start = CGPoint.zero
        func number(_ token: String) -> CGFloat { CGFloat(Double(token) ?? 0) }
        func isCommand(_ token: String) -> Bool { token.range(of: #"^[A-Za-z]$"#, options: .regularExpression) != nil }
        while index < tokens.count {
            if isCommand(tokens[index]) { command = tokens[index]; index += 1 }
            guard !command.isEmpty else { break }
            let relative = command == command.lowercased()
            switch command.uppercased() {
            case "M", "L":
                guard index + 1 < tokens.count, !isCommand(tokens[index]) else { continue }
                var point = CGPoint(x: number(tokens[index]), y: number(tokens[index + 1])); index += 2
                if relative { point.x += current.x; point.y += current.y }
                if command.uppercased() == "M" { result.move(to: point); start = point; command = relative ? "l" : "L" }
                else { result.addLine(to: point) }
                current = point
            case "H":
                guard index < tokens.count, !isCommand(tokens[index]) else { continue }
                let x = number(tokens[index]) + (relative ? current.x : 0); index += 1
                current = CGPoint(x: x, y: current.y); result.addLine(to: current)
            case "V":
                guard index < tokens.count, !isCommand(tokens[index]) else { continue }
                let y = number(tokens[index]) + (relative ? current.y : 0); index += 1
                current = CGPoint(x: current.x, y: y); result.addLine(to: current)
            case "C":
                guard index + 5 < tokens.count, !isCommand(tokens[index]) else { continue }
                var c1 = CGPoint(x: number(tokens[index]), y: number(tokens[index + 1]))
                var c2 = CGPoint(x: number(tokens[index + 2]), y: number(tokens[index + 3]))
                var end = CGPoint(x: number(tokens[index + 4]), y: number(tokens[index + 5])); index += 6
                if relative { c1.x += current.x; c1.y += current.y; c2.x += current.x; c2.y += current.y; end.x += current.x; end.y += current.y }
                result.addCurve(to: end, control1: c1, control2: c2); current = end
            case "Q":
                guard index + 3 < tokens.count, !isCommand(tokens[index]) else { continue }
                var control = CGPoint(x: number(tokens[index]), y: number(tokens[index + 1]))
                var end = CGPoint(x: number(tokens[index + 2]), y: number(tokens[index + 3])); index += 4
                if relative { control.x += current.x; control.y += current.y; end.x += current.x; end.y += current.y }
                result.addQuadCurve(to: end, control: control); current = end
            case "Z":
                result.closeSubpath(); current = start; command = ""
            default:
                command = ""
            }
        }
        return result
    }

