enum PermissionGlyphKind: String {
    case readOnly = "read-only"
    case workspaceWrite = "workspace-write"
    case fullAccess = "danger-full-access"
}

/// Exact permission glyph geometry from WebUI PermissionSelect.tsx.
struct PermissionGlyph: View {
    let value: String
    var size: CGFloat = 16

    var body: some View {
        Canvas { context, canvasSize in
            let scale = min(canvasSize.width, canvasSize.height) / 16
            let transform = CGAffineTransform(scaleX: scale, y: scale)
            switch PermissionGlyphKind(rawValue: value) {
            case .readOnly:
                context.stroke(DeepSeekIcon.svgPath(Self.shield).applying(transform),
                               with: .foreground, style: StrokeStyle(lineWidth: 1.31831 * scale, lineJoin: .round))
                context.fill(DeepSeekIcon.svgPath(Self.check).applying(transform), with: .foreground)
            case .workspaceWrite:
                for source in Self.workspace { context.fill(DeepSeekIcon.svgPath(source).applying(transform), with: .foreground) }
            case .fullAccess:
                context.stroke(DeepSeekIcon.svgPath(Self.shield).applying(transform),
                               with: .foreground, style: StrokeStyle(lineWidth: 1.31831 * scale, lineJoin: .round))
                context.fill(DeepSeekIcon.svgPath(Self.exclamationTop).applying(transform), with: .foreground)
                context.fill(DeepSeekIcon.svgPath(Self.exclamationBottom).applying(transform), with: .foreground)
            case nil:
                break
            }
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }

